operations.order_operation:
query GrowthHeartbeatDelta($filter: String!, $after: String) {
  shop { id name ianaTimezone currencyCode primaryDomain { host } }
  orders(first: 50, after: $after, query: $filter, sortKey: CREATED_AT) {
    nodes {
      id createdAt test cancelledAt sourceName
      displayFinancialStatus displayFulfillmentStatus
      currentSubtotalPriceSet { shopMoney { amount currencyCode } }
      currentTotalPriceSet { shopMoney { amount currencyCode } }
      currentTotalTaxSet { shopMoney { amount currencyCode } }
      totalRefundedSet { shopMoney { amount currencyCode } }
      lineItems(first:50) {
        nodes { currentQuantity product { id } variant { id } }
        pageInfo { hasNextPage endCursor }
      }
    }
    pageInfo { hasNextPage endCursor }
  }
}

operations.fulfillment_operation:
query ChangedBasketFulfillment($id: ID!) {
  shop { id name primaryDomain { host } currencyCode }
  order(id: $id) {
    displayFinancialStatus displayFulfillmentStatus
    currentSubtotalPriceSet { shopMoney { amount currencyCode } }
    totalRefundedSet { shopMoney { amount currencyCode } }
    fulfillments(first:50) {
      status displayStatus totalQuantity deliveredAt inTransitAt estimatedDeliveryAt
      trackingInfo { company }
      fulfillmentLineItems(first:50) {
        nodes { quantity lineItem { product { id } variant { id } } }
        pageInfo { hasNextPage endCursor }
      }
      events(first:50) {
        nodes { status happenedAt }
        pageInfo { hasNextPage endCursor }
      }
    }
  }
}
